  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition);
}

.resource-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-sm);
}

.resource-card h3 { font-size: 1rem; font-weight: 700; margin-bottom: 8px; }
.resource-card p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; }

.resource-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 12px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
}

/* ─── SOCIAL PROOF ─── */
.social-proof {
  text-align: center;
  padding: 60px 0;
  border-top: 1px solid var(--gray-200);
}

.social-logos {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.5;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--gray-400);
}

/* ─── FOOTER ─── */
.footer {
  background: var(--primary);
  color: rgba(255,255,255,0.7);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.7;
  margin-top: 16px;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 0.813rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.5);
  padding: 4px 0;
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  font-size: 0.813rem;
}

/* ─── MEMBERSHIP TIERS ─── */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.tier-card {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 32px;
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: all var(--transition);
}

.tier-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }

.tier-card h3 { font-size: 1.2rem; font-weight: 700; margin-bottom: 8px; }
.tier-price { font-size: 2rem; font-weight: 800; color: var(--accent); margin-bottom: 16px; }
.tier-features { text-align: left; }
.tier-features li { padding: 6px 0; font-size: 0.875rem; color: var(--gray-600); }
.tier-features li::before { content: '✓ '; color: var(--green); font-weight: 700; }

/* ─── RESPONSIVE ─── */
@media (max-width: 1024px) {
  .hero h1 { font-size: 2.8rem; }
  .section-header h2 { font-size: 2rem; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .hamburger { display: flex; }
  .nav-links {
    display: none;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--white);
    flex-direction: column;
    padding: 24px;
    gap: 16px;
    border-bottom: 1px solid var(--gray-200);
    box-shadow: var(--shadow-md);
  }
  .nav-links.open { display: flex; }
  .hero { padding: 48px 0 40px; }
  .hero h1 { font-size: 2.2rem; }
  .hero p { font-size: 1rem; }
  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .stat-item h3 { font-size: 2rem; }
  .section { padding: 56px 0; }
  .testimonial-card { min-width: calc(100% - 16px); }
  .pricing-highlight { padding: 40px 24px; }
  .cta-banner { padding: 40px 24px; margin: 0 16px; }
  .cta-banner h2 { font-size: 1.8rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; }
  .mock-sidebar { display: none; }
  .tab-content { aspect-ratio: 4/3; }
  .why-tabs { gap: 6px; }
  .why-tab { padding: 8px 14px; font-size: 0.813rem; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.8rem; }
  .hero-actions { flex-direction: column; align-items: center; }
  .section-header h2 { font-size: 1.6rem; }
  .price-tag { font-size: 2.2rem; }
}

/* ─── ANIMATIONS ─── */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

