file.content:
.hero-tabs {
  margin-top: 48px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.tab-toggle {
  display: inline-flex;
  background: var(--gray-100);
  border-radius: 50px;
  padding: 4px;
  margin-bottom: 32px;
}

.tab-toggle button {
  padding: 10px 24px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-500);
  transition: all var(--transition);
}

.tab-toggle button.active {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.tab-content {
  width: 100%;
  max-width: 960px;
  background: var(--gray-100);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.tab-panel {
  display: none;
  width: 100%;
  height: 100%;
  padding: 40px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  animation: fadeIn 0.4s ease;
}

.tab-panel.active { display: flex; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }

